mapper.select:
SELECT e.* FROM interpretation_embedding e LEFT JOIN interpretation_session s ON e.session_id COLLATE utf8mb4_unicode_ci = s.session_id COLLATE utf8mb4_unicode_ci LEFT JOIN meeting m ON e.meeting_id = m.id WHERE (s.user_id = #{userId} OR m.user_id = #{userId}) AND (s.session_id IS NULL OR COALESCE(s.deleted, 0) = 0) AND (m.id IS NULL OR COALESCE(m.deleted, 0) = 0)
AND e.meeting_id = #{filterMeetingId}
AND e.speaker_name COLLATE utf8mb4_unicode_ci LIKE CONCAT('%', #{filterSpeakerName}, '%')
AND COALESCE(s.start_time, m.scheduled_time, m.create_time) >= #{filterSince}
AND COALESCE(e.index_status, 'READY') = 'READY' AND ( e.embedding_profile = #{embeddingProfile} OR e.embedding_profile = 'default' OR e.embedding_profile IS NULL ) ORDER BY CASE WHEN e.embedding_profile = #{embeddingProfile} THEN 0 WHEN e.embedding_profile = 'default' THEN 1 ELSE 2 END, e.id DESC LIMIT #{candidateLimit}
